function validate([s]) {
  if (typeof s !== 'string' || s.length < 3 || s.length > 1000) return 's needs 3 to 1000 characters.';
  if (!/^[XO]+$/.test(s)) return "s may contain only 'X' and 'O'.";
  return null;
}

