function minimumMoves(s) {
  // dp[j] = fewest moves that clear the prefix s[0..j); the last X is either already O
  // or covered by a window ending at j - 1 (clamped to the first three positions).
  const n = s.length;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;
  for (let j = 1; j <= n; j++) {
    if (s[j - 1] === 'O') dp[j] = dp[j - 1];
    dp[j] = Math.min(dp[j], 1 + dp[Math.max(0, j - 3)]);
  }
  return dp[n];
}

