function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 3 + Math.floor(rand() * 10);
  const density = rand();
  let s = '';
  for (let k = 0; k < n; k++) s += rand() < density ? 'X' : 'O';
  return [s];
}
